    deployment=load(OUT/'mainnet-deployment/result.json');mint=load(OUT/'mainnet-small-mint/result.json');ack=load(OUT/'destination-ack/result.json');daily=load(COORD/'evidence/tee/b24-daily/20261114/complete.json');assert all(x['passed'] for x in (deployment,mint,ack)) and daily['six_validator_verified']
    funding=load(OUT/'funding-final/sequence.json');assert funding['prepared'] and not funding['executed'];paid=load(OUT/'real-export/operations.json')[0]['operation']['max_settlement_value_atoms'];e=load(OUT/'deployment-expected.json');o=e['operator'];s=load(ack['final_snapshot']);r=item(s['ledger']['pftl_uniswap_routes'],'route_id',ROUTE);n=item(s['ledger']['nav_assets'],'asset_id',B24);six=read_six();save(OUT/'final-six.json',six);assert len(points(six))==1 and six[0]['server']['ledger']['height']==s['tip']['height'] and six[0]['server']['ledger']['state_root']==s['tip']['state_root']
    w=Web3(Web3.HTTPProvider(PUBLIC_RPC,request_kwargs={'timeout':60}));block=w.eth.block_number;t=contract(w,'WrappedVenueNAVCoin',o['token']);c=contract(w,'PFTLUniswapPrimaryMarketV3',o['controller']);v=contract(w,'PFTLReceiptFinalityVerifierV2',o['verifier']);assert t.functions.totalSupply().call()==t.functions.balanceOf(o['address']).call()==r['ethereum_spendable_supply_atoms']==1000000 and r['outstanding_bridge_claims_atoms']==0 and invariant(r)
