    result=dict(passed=True,mainnet_deployed=True,real_export_proof_mint_ack_verified=True,pool_initialized=True,wallet_ethereum_available=False,observed_at=datetime.now(timezone.utc).isoformat(),ethereum_block=block,operator=o['address'],addresses={k:o[k] for k in ('token','verifier','controller')},runtime_hashes={k:e['runtime'][k+'_runtime_code_hash'] for k in ('token','verifier','controller')},mainnet_transactions=deployment['receipts']+mint['receipts'],gas_used=deployment['gas_used']+mint['gas_used'],gas_spent_wei=deployment['gas_spent_wei']+mint['gas_spent_wei'],ETH_left_wei=eth,USDC_atoms=usdc,operator_nonce=w.eth.get_transaction_count(o['address'],'pending'),wrapper_supply_atoms=1000000,operator_wrapper_balance_atoms=1000000,mint_paused=True,return_paused=True,ownership_retained=True,controller_locked=True,pool_id=e['pool_id'],pool=pool_state,native_height=s['tip']['height'],native_state_root=s['tip']['state_root'],native_supply_atoms=r['authorized_valid_supply_atoms'],native_spendable_atoms=r['pftl_spendable_supply_atoms'],native_ethereum_atoms=r['ethereum_spendable_supply_atoms'],pending_claims_atoms=0,reserve_F_atoms=r['settlement_reserve_atoms'],aggregate_non_nav_spread_atoms=r['v2']['non_nav_spread_atoms'],NAV_atoms=n['nav_per_unit'],NAV_epoch=n['finalized_epoch'],verifier_finalized_height=v.functions.latestFinalizedHeight().call(),verifier_checkpoint=hx(v.functions.latestCheckpointCommitment().call()),daily=daily,fee_cap_wei=fee,future_gas_budget=budget,future_cost_max_wei=budget*fee,remaining_ETH_covers_future_proof_mint_approvals_ingress_LP=remaining_covered,real_7025_USDC_sequence_executed=False,returns_supported=False)
